/**
 * 负责：从原配置与显式选项装配 World、角色组件、机制和真实游戏运行时。
 * 输入：BoardConfig、角色与随机源选项；输出：原初始化对象及同一参数和 RulePlan owner。
 * 先在原 deal fork 后验证支持范围并洗牌，再初始化实体；不读取模型认证或选择玩家动作。
 * 校验后的配置克隆在角色初始化前冻结，原 World、actor、RNG 和调用方均不冻结。
 * PhaseManager 创建规则计划，流水线、开局上下文和记录入口消费同一引用。
 */
import {
  createAliveComponent,
  createBadgeComponent,
  createCampComponent,
  createStatusMarksComponent,
  createVotingRightComponent,
} from "../game/observation/component-presentation";
import { installNobleBodyAuthority } from "../game/mechanisms/roles/noble_secret_body/authority";
import { installAnimalAuthority } from "../game/mechanisms/roles/animal_dream/authority";
import { buildSupportedRoleDeck } from "../rulesets/supported-role-deck";
import { BoardParameters, bindBoardParameters } from "../rulesets/board-parameters";
import type { RulePlan } from "../rulesets/rule-plan";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { installRadiantEclipseBoard } from "../game/mechanisms/roles/radiant_eclipse/night_frame";
import { installMistRavenBoard } from "../game/mechanisms/roles/mist_raven/night_frame";
import { installScholarMentorBoard } from "../game/mechanisms/roles/scholar_mentor/night_frame";
import { installTimeConsortBoard } from "../game/mechanisms/roles/time_wolf_consort/night_frame";
import { installWolfSorcererBoard } from "../game/mechanisms/roles/wolf_sorcerer/night_frame";
import { installTricksterBoard } from "../game/mechanisms/roles/trickster/night_frame";
import { installOrderPrinceBoard } from "../game/mechanisms/roles/order_prince/authority";
import { installMagicianBoard } from "../game/mechanisms/roles/magician/night_frame";
import { installNightmareBoard } from "../game/mechanisms/roles/nightmare_shadow/night_frame";
import { installEvilKnightBoard } from "../game/mechanisms/roles/evil_knight/night_frame";
import { installDemonHunter } from "../game/mechanisms/roles/demon_hunter/authority";
import { WinConditionRegistry as PureWhiteWinRegistry } from "../game/mechanisms/registries/win_condition_registry";
import { createEliminationWinConditionSpecs } from "../game/mechanisms/win_conditions/default_specs";
import { installGhostBride } from "../game/mechanisms/roles/ghost_bride/authority";
import { installLonelyGirl } from "../game/mechanisms/roles/lonely_girl/lifecycle";
import { installWildChild } from "../game/mechanisms/roles/wild_child/lifecycle";
import { installInitialRoster } from "../core/domain/initial_roster";
import { installShapeshifterDeal } from "../game/mechanisms/roles/shapeshifter/deal";
import { installThiefDeal } from "../game/mechanisms/roles/thief/deal";
import { supportsWallRoles } from "../game/mechanisms/events/wall_notes/authority";
import { text } from "@ai-werewolf-arena/game-text";

import { COMPONENT } from "../core/domain/components/names";
import type { RoleComponent } from "../core/domain/components/role";
import { createRoleComponent } from "../game/observation/role-presentation";

import { createVictoryComponent } from "../core/domain/components/victory";
import { createIdentityComponent } from "../core/domain/entities/player";
import { BoardConfig, EntityId, Role } from "../core/domain/model";
import {
  getDefaultWinConditionRegistry,
  getDefaultRoleCatalog,
  assignInitialSheriff,
  createDefaultRoleRegistry,
} from "../game/mechanisms";
import { ConditionRegistry } from "../core/domain/registries/condition_registry";
import { DamageResolutionSystem } from "../core/domain/systems/damage_resolution_system";
import { World } from "../core/domain/world";
import { PhaseManager } from "../game/engine/phase_manager";
import { ToolGateway } from "../game/gateway/tool_gateway";
import { createRandom, shuffled, type RandomSource } from "../core/domain/random";
import type { Locale } from "@ai-werewolf-arena/game-contract";

/**
 * bootstrap 负责把“配置”装配成“可运行对局上下文”。
 * 这是服务层启动游戏引擎的唯一入口。
 */
export interface BootstrapResult {
  world: World;
  readonly boardConfig: ReadonlyBoardConfig;
  readonly parameters: BoardParameters;
  readonly rulePlan: RulePlan;
  phaseManager: PhaseManager;
  playerIds: EntityId[];
  random: RandomSource;
  dealMode: "random" | "fixed";
}

export interface BootstrapOptions {
  locale?: Locale;
  playerNames?: Readonly<Record<string, string>>;
  random?: RandomSource;
  /** 仅供 controller fixture：明确牌堆仍按原数量严格验证。 */
  fixedRoles?: readonly Role[];
  /** 显式离线因果测试输入，不是板子或模型参数。 */
  faultPlan?: unknown;
}

/**
 * 按板子配置完成一次完整引擎装配，返回可直接运行的上下文对象。
 */
export function bootstrapGame(
  config: BoardConfig,
  options: BootstrapOptions = {},
): BootstrapResult {
  const world = new World(options.locale);
  const random = options.random ?? createRandom();
  // 先完成实体与组件初始化，再创建系统与管理器，避免空引用。
  const initialized = createPlayers(world, config, options, random);
  const playerIds = initialized.playerIds;
  const parameters = initialized.parameters;
  const boardConfig = parameters.board;
  assignInitialSheriff(world, boardConfig, playerIds);

  const roleRegistry = createDefaultRoleRegistry();
  const damageResolutionSystem = new DamageResolutionSystem();
  const conditionRegistry = new ConditionRegistry(
    boardConfig.pureWhite || boardConfig.animalDream
      ? new PureWhiteWinRegistry(
          createEliminationWinConditionSpecs(
            boardConfig.pureWhite?.eliminationPriority ?? "awa_wolf_priority_v1",
          ),
        )
      : getDefaultWinConditionRegistry(),
  );
  const toolGateway = new ToolGateway();

  const phaseManager = new PhaseManager(
    world,
    boardConfig,
    toolGateway,
    roleRegistry,
    conditionRegistry,
    damageResolutionSystem,
    random,
    { faultPlan: options.faultPlan },
  );

  return Object.freeze({
    world,
    boardConfig,
    parameters,
    rulePlan: phaseManager.getRulePlan(),
    phaseManager,
    playerIds,
    random,
    dealMode: options.fixedRoles ? "fixed" : "random",
  });
}

function createPlayers(
  world: World,
  inputConfig: BoardConfig,
  options: BootstrapOptions,
  random: RandomSource,
): { playerIds: EntityId[]; parameters: BoardParameters } {
  const fixedRoles = options.fixedRoles;
  const dealRandom = random.fork("deal");
  const candidateParameters = BoardParameters.compile(inputConfig);
  const config = candidateParameters.board;
  const roles = buildRoleDeck(config, fixedRoles, dealRandom);
  const parameters = bindBoardParameters(world, candidateParameters);
  const ids: EntityId[] = [];
  const roleCatalog = getDefaultRoleCatalog();

  for (let seat = 1; seat <= config.boardSize; seat++) {
    const entityId = world.createEntity();
    const role = roles[seat - 1];
    // 初始 Camp 是唯一待安装对象；init 可改它，运行 source 则只查询实际 World，不回退 draft。
    const initialCamp = createCampComponent(roleCatalog.getCamp(role), world.locale);
    const roleComp = createRoleComponent(role, world.locale);
    const currentCamp = () => world.getComponent(entityId, COMPONENT.Camp);
    roleCatalog.applyRuntime(roleComp, { boardConfig: config, locale: world.locale, world, initialCamp, currentCamp });

    world.addComponent(
      entityId,
      COMPONENT.Identity,
      createIdentityComponent(
        entityId,
        seat,
        options.playerNames?.[String(seat)] ??
          text(world.locale, "common.player_name", { id: seat }),
      ),
    );
    world.addComponent(entityId, COMPONENT.Role, roleComp);
    world.addComponent(entityId, COMPONENT.Camp, initialCamp);
    const membership = roleCatalog.requireRuntime(role).initialVictoryAffiliations;
    world.addComponent(
      entityId,
      COMPONENT.Victory,
      createVictoryComponent(
        typeof membership === "function"
          ? membership(roleComp, { boardConfig: config, locale: world.locale, initialCamp, currentCamp })
          : (membership ?? [{ kind: "faction", faction: (() => {
              // 仅默认分支在原字段点晚查；自定义 membership 仍持独立无 World 的上下文。
              const camp = currentCamp();
              if (!camp) throw new Error("role_current_camp_missing");
              return camp.camp;
            })() }]),
      ),
    );
    world.addComponent(entityId, COMPONENT.Alive, createAliveComponent(true, world.locale));
    world.addComponent(entityId, COMPONENT.StatusMarks, createStatusMarksComponent(world.locale));
    world.addComponent(
      entityId,
      COMPONENT.VotingRight,
      createVotingRightComponent(1, true, world.locale),
    );
    world.addComponent(entityId, COMPONENT.Badge, createBadgeComponent(false, false, world.locale));
    ids.push(entityId);
  }

  if (config.roleSetups.some((row) => row.role === Role.Thief && row.count === 1))
    installThiefDeal(world, roles, ids);
  if (config.roleSetups.some((row) => row.role === Role.Shapeshifter && row.count === 1))
    installShapeshifterDeal(world, roles, ids);
  installInitialRoster(world);
  if (config.animalDream) installAnimalAuthority(world, config);
  if (roles.includes(Role.Alchemist) || roles.includes(Role.RavenClawWolf))
    installMistRavenBoard(world);
  if (config.radiantEclipse) installRadiantEclipseBoard(world);
  if (roles.includes(Role.DayScholar) || roles.includes(Role.NightMentor))
    installScholarMentorBoard(world);
  if (roles.includes(Role.TimeWolfConsort)) installTimeConsortBoard(world);
  if (roles.includes(Role.Trickster)) installTricksterBoard(world);
  if (roles.includes(Role.Magician)) installMagicianBoard(world);
  if (roles.includes(Role.WolfSorcerer)) installWolfSorcererBoard(world);
  if (roles.includes(Role.OrderPrince)) installOrderPrinceBoard(world);
  if (roles.includes(Role.EvilKnight)) installEvilKnightBoard(world);
  if (roles.includes(Role.NightmareShadow)) installNightmareBoard(world);
  if (config.nobleSecretBody)
    installNobleBodyAuthority(
      world,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.NightNoble)!,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.AwakenedIdiot)!,
    );
  if (roles.includes(Role.DemonHunter)) installDemonHunter(world, config);
  if (roles.includes(Role.GhostBride)) installGhostBride(world, config);
  installWildChild(world, config);
  installLonelyGirl(world, config);
  return { playerIds: ids, parameters };
}

function buildRoleDeck(
  config: ReadonlyBoardConfig,
  fixedRoles: readonly Role[] | undefined,
  random: RandomSource,
): Role[] {
  const deck = buildSupportedRoleDeck(config, fixedRoles, getDefaultRoleCatalog, supportsWallRoles);
  return fixedRoles ? deck : shuffled(deck, random);
}

/**
 * 负责向领域调用方公开 core 的既有出口；输入为 domain 导出的类型、组件工厂、存储与运行端口，
 * 输出保持同一公开绑定，不复制实例、建立第二份状态或替原所有者授予权限。
 * 原重导出与其叶模块加载关系保持；具体初始化、副作用和生命周期仍归实际实现。
 */
export * from "./domain";

/**
 * 负责向运行装配及场景调用方提供既有板子预设。
 * 固定六人基础牌组，关闭警长与四个钩子，并按数组顺序声明屠城、狼达半两项目标。
 * 输入为本模块固定声明，输出为原 BoardConfig 数据；不在此解析、验证或冻结配置。
 * 预设不代表任意角色组合受支持，也不创建 World、支付资源或授予行动权限；规范化与有限支持由调用方继续执行。
 */
import { BoardConfig, Role, WinCondition } from "../../core/domain/model";

/** 六人基础输入供夜昼流转与守卫／预言家场景消费；本声明本身不执行验证。 */
export const sixPlayerMvpConfig: BoardConfig = {
  boardSize: 6,
  enableSheriff: false,
  winConditions: [WinCondition.SlaughterCity, WinCondition.WolfReachHalf],
  hooks: {
    onDaybreak: false,
    onPreElection: false,
    onPreVote: false,
    onPerSpeechGap: false,
  },
  roleSetups: [
    { role: Role.Wolf, count: 2 },
    { role: Role.Villager, count: 2 },
    { role: Role.Seer, count: 1 },
    { role: Role.Guard, count: 1 },
  ],
};

/**
 * 负责一个会话的复盘聚合、增量文件内容和终结发布；输入为事件、行动记录与结束元数据。
 * 输出为公开复盘、玩家视角和严格复现归档；聚合和存储仍由各自具体模块持有。
 * 生命周期模块唯一拥有定时器、队列、关闭与首次终结 Promise；本管理器保留必需失败账本。
 * 严格前缀写失败即登记，最终发布仍尝试完成；单个失败原样传播，多失败保持原顺序聚合。
 * 此处不控制游戏阶段或资源提交，不把可选诊断写入失败改成游戏错误。
 */
import type { Locale } from "@ai-werewolf-arena/game-text";
import { formatErrorDiagnostic } from "../utils/error_diagnostic";
import path from "path";
import type {
  DebugSummaryInput,
  ReplayFinalizeMeta,
  ReplayRecordDebugReportInput,
  ReplayRecordLogicOpInput,
  ReplayRecordPlayerEventInput,
  ReplayRecordPlayerRoundInput,
  ReplayRecordPublicEventInput,
  ReplaySessionMeta,
} from "./contracts";
import { currentRecordingIdentities, createPublicReplayArchive, createReproductionArchive, createManifestArchive, createPlayerViewArchive } from "./archive_identity";
import { createReplayDocument } from "./replay_document";
import { ReplayFileStore } from "./file_store";
import { ReplaySessionAggregate } from "./session_aggregate";
import { getSessionRecorder } from "./recording_context";
import { type ReproductionFailureScope, type ReproductionMetadata } from "./reproduction";
import { ReproductionTrace } from "./reproduction-trace";
import { SessionRecordingLifecycle } from "./session-recording-lifecycle";

/** 文件内容、严格失败及归档发布的唯一编排者；刷盘排程由具体生命周期实例持有。 */
export class SessionRecordManager {
  private readonly lifecycle = new SessionRecordingLifecycle(
    () => this.flushDirtyFiles(),
    (error) => {
      console.warn(
        `[observability] replay_flush_failed err=${formatErrorDiagnostic(error, this.displayLocale)}`,
      );
    },
  );
  private dirtyPublicTimeline = false;
  private dirtyLogicOps = false;
  private dirtyDebugReports = false;
  private readonly dirtyPlayers = new Set<number>();
  private reproduction?: ReproductionTrace;
  private dirtyReproduction = false;
  // 公开初始化档尚无严格来源；beginReproduction 后只捕获实际元数据，不向历史档补写当前身份。
  private recordingIdentities = currentRecordingIdentities();
  private replayEventCursor?: () => number;
  setReplayEventCursor(cursor: () => number): void {
    if (this.replayEventCursor || this.reproduction)
      throw Error("reproduction_event_cursor_already_bound");
    this.replayEventCursor = cursor;
  }
  get reproductionSettlementCount(): number {
    return this.reproduction?.settlementCount ?? 0;
  }
  get reproductionDecisionCount(): number {
    return this.reproduction?.decisionCount ?? 0;
  }
  private readonly mandatoryFlushFailures: unknown[] = [];

  private constructor(
    private readonly aggregate: ReplaySessionAggregate,
    private readonly store: ReplayFileStore,
    readonly displayLocale: Locale,
  ) {}

  static async create(
    sessionMeta: ReplaySessionMeta,
    recordRootDir: string,
    displayLocale: Locale = sessionMeta.locale ?? "zh-CN",
  ): Promise<SessionRecordManager> {
    const store = new ReplayFileStore(
      path.join(recordRootDir, sessionMeta.sessionId),
      displayLocale,
    );
    const manager = new SessionRecordManager(
      new ReplaySessionAggregate(sessionMeta),
      store,
      displayLocale,
    );
    await store.initialize();
    await manager.writeInitialFiles();
    return manager;
  }

  get sessionId(): string {
    return this.aggregate.sessionMeta.sessionId;
  }
  /** 严格复现实际序列化的领域操作数，不包含 AI 诊断操作。 */
  get reproductionOperationCount(): number {
    return this.aggregate.reproductionOperationCount;
  }
  get sessionDir(): string {
    return this.store.sessionDir;
  }

  beginReproduction(
    metadata: ReproductionMetadata,
    liveEvents?: () => readonly import("../core").GameEvent[],
  ): ReproductionTrace {
    if (this.lifecycle.isClosed || this.reproduction)
      throw new Error("reproduction_scope_already_started_or_closed");
    this.aggregate.enableReproduction();
    this.reproduction = new ReproductionTrace(
      metadata,
      () => {
        if (this.lifecycle.isClosed) return;
        this.dirtyReproduction = true;
        this.lifecycle.scheduleFlush();
      },
      liveEvents,
    );
    // 不以来源声明驱动新刷盘；下次原公开发布或最终发布自然携带已捕获身份。
    this.recordingIdentities = currentRecordingIdentities(this.reproduction.recordedMetadataIdentity());
    return this.reproduction;
  }

  noteReproductionFailure(scope: ReproductionFailureScope, error: unknown): void {
    this.reproduction?.noteFailure(scope, error);
  }

  recordPublicEvent(input: ReplayRecordPublicEventInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPublicEvent(input);
    this.dirtyPublicTimeline = true;
    this.lifecycle.scheduleFlush();
  }

  /** 必需因果输入在 closing 起即拒绝；普通诊断仍保留原有的关闭前追加语义。 */
  recordRequiredLogicOp(input: ReplayRecordLogicOpInput): void {
    if (this.lifecycle.isClosed || this.lifecycle.isClosing)
      throw new Error("mandatory_logic_op_recording_closed");
    this.recordLogicOp(input);
  }

  recordLogicOp(input: ReplayRecordLogicOpInput): void {
    if (this.lifecycle.isClosed) return;
    const eventCount = this.reproduction?.ownedEventCursor ?? this.replayEventCursor?.();
    this.aggregate.recordLogicOp(eventCount === undefined ? input : { ...input, eventCount });
    this.dirtyLogicOps = true;
    this.lifecycle.scheduleFlush();
  }

  recordPlayerRound(input: ReplayRecordPlayerRoundInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPlayerRound(input);
    this.dirtyPlayers.add(input.playerId);
    this.lifecycle.scheduleFlush();
  }

  recordPlayerEvent(input: ReplayRecordPlayerEventInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPlayerEvent(input);
    this.dirtyPlayers.add(input.playerId);
    this.lifecycle.scheduleFlush();
  }

  recordDebugReport(input: ReplayRecordDebugReportInput): string {
    if (this.lifecycle.isClosed) return "rb-closed";
    const reportId = this.aggregate.recordDebugReport(input);
    this.dirtyDebugReports = true;
    this.lifecycle.scheduleFlush();
    return reportId;
  }

  flushNow(): Promise<void> {
    return this.lifecycle.flushNow();
  }

  finalize(meta: ReplayFinalizeMeta): Promise<DebugSummaryInput> {
    return this.lifecycle.finalize(() => this.persistFinalRecord(meta));
  }

  writeDebugSummary(markdown: string): Promise<void> {
    return this.store.writeText("debug_summary.md", markdown);
  }

  private async persistFinalRecord(meta: ReplayFinalizeMeta): Promise<DebugSummaryInput> {
    // closing 在首个 await 前生效；前缀完成后关闭追加，再发布最终文件。
    await this.lifecycle.beginClosing(meta);
    this.lifecycle.markClosed();

    const manifest = this.aggregate.buildManifest(meta);
    const replayDocument = this.buildReplayArchive(meta);
    const reproducible = () => {
      const input = this.aggregate.debugSummaryInput();
      const operations = (input.logicOps ?? [])
        .filter((op) => op.scope !== "llm_action_provider")
        .map(({ seq: _seq, timestamp: _timestamp, ...op }) => op);
      return this.reproduction!.build({
        operations,
        termination: { reason: meta.finishReason, winner: meta.winner },
      });
    };
    const required = await Promise.allSettled([
      this.store.writeJsonStrict("manifest.json", createManifestArchive(manifest, this.recordingIdentities)),
      this.store.writeJsonStrict("replay.json", replayDocument),
      ...(this.reproduction
        ? [
            Promise.resolve().then(() =>
              this.store.writeJsonStrict("reproduction.json", createReproductionArchive(reproducible())),
            ),
          ]
        : []),
    ]);
    await Promise.all([
      this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
      this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload()),
      this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload()),
    ]);

    const playerViews = this.aggregate.normalizedPlayerViews();
    await Promise.all(
      playerViews.map((view) =>
        this.store.writeJson(`players/player_${view.player_id}.json`, createPlayerViewArchive(view, this.recordingIdentities)),
      ),
    );

    // 已失败的严格前缀先列出，再列本次必需终档失败；成功发布不撤销旧失败。
    const failures = [
      ...this.mandatoryFlushFailures,
      ...required
        .filter((result): result is PromiseRejectedResult => result.status === "rejected")
        .map((result) => result.reason),
    ];
    if (failures.length === 1) throw failures[0];
    if (failures.length) throw new AggregateError(failures, "session_record_finalization_failed");

    return {
      manifest,
      ...this.aggregate.debugSummaryInput(),
      sessionDir: this.sessionDir,
    };
  }

  private async writeInitialFiles(): Promise<void> {
    const results = await Promise.allSettled([
      this.store.writeJsonStrict("manifest.json", createManifestArchive(this.aggregate.buildManifest(), this.recordingIdentities)),
      this.store.writeJsonStrict("replay.json", this.buildReplayArchive()),
      this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
      this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload()),
      this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload()),
    ]);
    const failures = results
      .filter((result): result is PromiseRejectedResult => result.status === "rejected")
      .map((result) => result.reason);
    if (failures.length === 1) throw failures[0];
    if (failures.length) throw new AggregateError(failures, "session_record_initialization_failed");
  }

  private async flushDirtyFiles(): Promise<void> {
    if (this.lifecycle.isClosed) return;
    if (this.dirtyReproduction && this.reproduction) {
      // 先消费本次脏位；严格失败登记在账本，后续仍可发布终档并报告此前失败。
      this.dirtyReproduction = false;
      try {
        await this.store.writeJsonStrict("reproduction.json", createReproductionArchive(this.reproduction.build()));
      } catch (error) {
        this.mandatoryFlushFailures.push(error);
        this.reproduction.noteFailure("recording", error);
        throw error;
      }
    }
    if (this.dirtyPublicTimeline) {
      this.dirtyPublicTimeline = false;
      await Promise.all([
        this.store.writeJson(
          "replay.json",
          this.buildReplayArchive(this.lifecycle.finalMetadata ?? undefined),
        ),
        this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
        this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      ]);
    }
    if (this.dirtyLogicOps) {
      this.dirtyLogicOps = false;
      await this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload());
    }
    if (this.dirtyDebugReports) {
      this.dirtyDebugReports = false;
      await this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload());
    }
    if (this.dirtyPlayers.size > 0) {
      const playerIds = [...this.dirtyPlayers];
      this.dirtyPlayers.clear();
      await Promise.all(
        playerIds.map(async (playerId) => {
          const view = this.aggregate.normalizedPlayerView(playerId);
          if (view) await this.store.writeJson(`players/player_${playerId}.json`, createPlayerViewArchive(view, this.recordingIdentities));
        }),
      );
      await Promise.all([
        this.store.writeJson(
          "manifest.json",
          createManifestArchive(this.aggregate.buildManifest(this.lifecycle.finalMetadata ?? undefined), this.recordingIdentities),
        ),
        this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      ]);
    }
  }

  private buildReplayArchive(meta?: ReplayFinalizeMeta) {
    return createPublicReplayArchive(createReplayDocument({
      manifest: this.aggregate.buildManifest(meta),
      events: this.aggregate.publicTimelinePayload().events,
    }), this.recordingIdentities);
  }
}

