/** 先保原版本／严格 envelope 准入，再按固定独立装配审核角色与板子；审核不执行游戏规则。 */
export function parseReproductionRecord(value: unknown): ReproductionRecord {
  // 新封装先按显式格式解包，历史裸 Tape 仍走下面原 schema 2／第一失败顺序。
  value = unwrapRecordingEnvelope(value, "strict_reproduction").payload;
  if (
    value &&
    typeof value === "object" &&
    "schemaVersion" in value &&
    value.schemaVersion !== REPRODUCTION_SCHEMA_VERSION
  )
    throw new Error("reproduction_schema_not_supported");
  const parsed = schema.safeParse(value);
  if (!parsed.success) throw new Error("reproduction_record_invalid");
  const result = parsed.data as unknown as ReproductionRecord;
  verifyReproductionMechanisms(result);
  return result;
}

/**
 * 负责归档机制 verifier 的完整固定装配。输入为 envelope／schema 已验证的 reproduction 数据；
 * 输出为原拒绝或全部审计通过，既有16步及其第一失败保持原顺序，不提前捕获可替换函数数组。
 * 贵族独立推导出的 audit 在原位置传给恶魔；其原 RedMoon／nativeStocks 子链仍由恶魔 verifier 消费。
 * 末尾丘比特／混血儿新增严格语义拒绝；schema 2 结构不变，公开 replay／player reader 不进入本装配。
 * 本入口不导入 World、生产结算或 checkpoint 写方，不授予行动权限；精确构建相容仍由执行器核对。
 * 独立 schema／ID／安全读器只确认结构，历史成功、失败前缀与规则推导仍属于各实际 verifier。
 */
import type { ReproductionRecord } from "../../recording/reproduction";
import { validateInitialIdentityRecord } from "./initial-identity";
import { validateWildChildRecord } from "./wild-child";
import { validateLonelyGirlRecord } from "./lonely-girl";
import { validateGhostBrideRecord } from "./ghost-bride/validate";
import { validateAnimalDreamRecord } from "./animal-dream/validate";
import { validateFragrantPairRecord } from "./fragrant-pair-seer/validate";
import { validateNobleSecretBodyRecord } from "./noble-secret-body/validate";
import { validateDemonHunterRecord } from "./demon-hunter/validate";
import { validateScholarMentorRecord } from "./scholar-mentor/validate";
import { validateMistRavenRecord } from "./mist-raven/validate";
import { validateRadiantEclipseRecord } from "./radiant-eclipse/validate";
import { validateTimeConsortRecord } from "./time-consort/validate";
import { validateWolfSorcererRecord } from "./wolf-sorcerer/validate";
import { validateTricksterRecord } from "./trickster/validate";
import { validateMagicianRecord } from "./magician/validate";
import { validateOrderPrinceRecord } from "./order-prince/validate";
import { validateCupidRecord } from "./cupid";
import { validateHybridRecord } from "./hybrid";

export function verifyReproductionMechanisms(result: ReproductionRecord): void {
  validateInitialIdentityRecord(result);
  validateWildChildRecord(result);
  validateLonelyGirlRecord(result);
  validateGhostBrideRecord(result);
  validateAnimalDreamRecord(result);
  validateFragrantPairRecord(result);
  // 传递的是由归档重建的审计数据，不是运行时 owner、原体或死亡提交回执。
  const noble = validateNobleSecretBodyRecord(result);
  validateDemonHunterRecord(result, noble);
  validateScholarMentorRecord(result);
  validateMistRavenRecord(result);
  validateRadiantEclipseRecord(result);
  validateTimeConsortRecord(result);
  validateWolfSorcererRecord(result);
  validateTricksterRecord(result);
  validateMagicianRecord(result);
  validateOrderPrinceRecord(result);
  // 只在原16步之后追加；旧严格 malformed 档可能在后续 sourceHash 兼容检查前被新语义拒绝。
  validateCupidRecord(result);
  validateHybridRecord(result);
}

/**
 * 负责丘比特严格 Tape 的独立选择、付款前缀、关系知识与胜利成员核验。
 * 输入是格式已准入的 Record，输出为接受或本族明确错误；本账本只读归档，不调用 World、生产关系／结算或 checkpoint 写方。
 * schema 2 下新增语义拒绝是明确的严格读取政策；公开 replay／player reader 不接本入口。
 * 失败 checkpoint 可保留已绑定关系、部分字段／归属或部分事实；关系死亡事实先于真实标死，不能单凭事实判死。
 * Tape 未记录生命版本、组件原引用、执行退休或逐请求事件游标；本核验不把这些缺席证据补成运行许可。
 */
import {
  Camp, DeathCause, Phase, Role, WinCondition,
  type LoversComponent, type VictoryAffiliation,
} from "@ai-werewolf-arena/game-contract";
import { CUPID_EVENT_TYPES, readCupidEventFact } from "@ai-werewolf-arena/game-contract/facts/cupid";
import { readVictoryResult } from "@ai-werewolf-arena/replay-contract";
import type { RecordedCheckpoint, RecordedDecision, ReproductionRecord } from "../../recording/reproduction";

const DEFAULT_POLICY = "netease_2017_cupid_follows_lovers_v1";
const fail: () => never = () => { throw new Error("reproduction_cupid_state_invalid"); };
const object = (value: unknown): Record<string, unknown> | null =>
  value !== null && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown> : null;
const positive = (value: unknown): value is number =>
  typeof value === "number" && Number.isSafeInteger(value) && value > 0;
const keys = (value: Record<string, unknown>, names: string[]) =>
  Object.keys(value).length === names.length && names.every((name) => Object.hasOwn(value, name));
// JSON 对象的键顺序不是游戏证据；数组顺序则保留配对、安装与事实发表的原含义。
function same(left: unknown, right: unknown): boolean {
  if (left === right) return true;
  if (Array.isArray(left) && Array.isArray(right))
    return left.length === right.length && left.every((value, i) => same(value, right[i]));
  const a = object(left), b = object(right);
  return !!a && !!b && Object.keys(a).length === Object.keys(b).length &&
    Object.keys(a).every((key) => Object.hasOwn(b, key) && same(a[key], b[key]));
}
function pair(value: unknown): [number, number] | null {
  return Array.isArray(value) && value.length === 2 && value.every(positive) && value[0] !== value[1]
    ? [value[0], value[1]] : null;
}
function actionPair(decision: RecordedDecision): [number, number] | null {
  if (decision.outcome.kind !== "action" || decision.outcome.action?.name !== "choose_lovers") return null;
  const args = decision.outcome.action.args;
  return pair([args.first_id, args.second_id]);
}
function requestIsCupid(decision: RecordedDecision): boolean {
  return decision.stage === "cupid" || decision.request.context.stage === "cupid" ||
    decision.request.allowedTools.includes("choose_lovers") ||
    (decision.outcome.kind === "action" && decision.outcome.action?.name === "choose_lovers");
}

export function validateCupidRecord(record: ReproductionRecord): void {
  const board = record.metadata.normalizedBoard;
  const owner = board.roleSetups.some((row) => row.role === Role.Cupid && row.count > 0);
  const facts = record.events.filter((event) => (CUPID_EVENT_TYPES as readonly string[]).includes(event.type));
  const decisions = record.decisions.filter(requestIsCupid);
  if (!owner) {
    if (facts.length || decisions.length || record.metadata.players.some((p) => p.role === Role.Cupid) ||
      record.decisions.some((d) => d.request.context.visible_events.some((e) => (CUPID_EVENT_TYPES as readonly string[]).includes(e.type))) ||
      record.checkpoints.some((cp) => cp.players.some((p) => Object.hasOwn(p.privateState, "cupid") || p.lovers !== undefined))) fail();
    return;
  }
  const initial = record.metadata.players;
  const actors = initial.filter((p) => p.role === Role.Cupid), actor = actors[0];
  const allowed = [Role.Cupid, Role.Wolf, Role.WolfKing, Role.WhiteWolfKing, Role.Seer, Role.Witch,
    Role.Guard, Role.Hunter, Role.Idiot, Role.Villager, Role.Knight, Role.Dreamer, Role.WolfBeauty];
  const wolfRoles = [Role.Wolf, Role.WolfKing, Role.WhiteWolfKing, Role.WolfBeauty];
  const policy = board.cupid?.policy ?? DEFAULT_POLICY;
  if (actors.length !== 1 || !actor || initial.length !== board.boardSize || record.metadata.initialDeal !== undefined ||
    !same(board.winConditions?.length ? board.winConditions : [board.winCondition ?? WinCondition.SlaughterCity], [WinCondition.SlaughterCity]) ||
    ![DEFAULT_POLICY, "lui_meme_lovers_only_v1"].includes(policy) ||
    new Set(initial.map((p) => p.id)).size !== initial.length ||
    initial.some((p) => !allowed.includes(p.role) || p.camp !== (wolfRoles.includes(p.role) ? Camp.Wolf : Camp.Good)) ||
    board.roleSetups.some((row) => initial.filter((p) => p.role === row.role).length !== row.count) ||
    initial.some((p) => !board.roleSetups.some((row) => row.role === p.role && row.count > 0)) || decisions.length > 3) fail();
  const byId = new Map(initial.map((p) => [p.id, p]));
  // 请求字段只证明录制的必选契约；没有真实期限、alias 或原体引用，不据它们授予行动许可。
  decisions.forEach((decision, index) => {
    const request = decision.request, context = request.context;
    if (decision.actorId !== actor.id || request.actorId !== actor.id || decision.day !== 1 || context.day !== 1 ||
      decision.stage !== "cupid" || context.stage !== "cupid" || request.phase !== Phase.Night ||
      decision.turn !== index + 1 || !same(request.allowedTools, ["choose_lovers"]) ||
      context.allow_fallback !== false || context.action_failure_policy !== "error" ||
      context.turn_constraints.min_valid_actions !== 1 || context.turn_constraints.max_valid_actions !== 1 ||
      !same(context.turn_constraints.required_any_tools, ["choose_lovers"]) ||
      (index === 0 ? context.retry_attempt !== undefined || context.retry_max !== undefined
        : context.retry_attempt !== index || context.retry_max !== 2)) fail();
  });

  let selected: [number, number] | null = null;
  const remember = (value: unknown) => {
    const next = pair(value);
    if (!next || next.some((id) => !byId.has(id)) || (selected && !same(selected, next))) fail();
    selected = next;
  };
  // 从已经写出的字段／事实确定唯一配对；无字段的未付尝试不会被猜成已提交。
  for (const event of facts) {
    const fact = readCupidEventFact(event.type, event.payload);
    if (!fact || event.audience !== undefined) fail();
    if (event.type === "cupid_lovers_chosen" || event.type === "cupid_relation_resolved") remember(fact.pairIds);
  }
  for (const cp of record.checkpoints) for (const player of cp.players) {
    if (player.lovers !== undefined) remember(player.lovers.pairIds);
    const state = object(player.privateState.cupid), choice = object(state?.choice);
    if (choice) remember(choice.pairIds);
  }
  const selectedPair = selected as [number, number] | null;
  // 首付款后阶段退出，只有最后一次同族请求可能解释已写配对；更早匹配不能遮住后继 known／null／无效回复。
  // 延后结算的末 error／pending 未保存候选，可由 CP／事实确定合法配对，但不能据它证明回复内容或许可。
  const lastDecision = decisions.at(-1);
  const opaqueDecision = lastDecision !== undefined && lastDecision.outcome.kind !== "action";
  if (selectedPair && (!lastDecision || (!opaqueDecision && !same(actionPair(lastDecision), selectedPair)))) fail();
  const relation: LoversComponent | null = selectedPair ? {
    actorId: actor.id, day: 1, policy, pairIds: selectedPair,
    pairCamps: [byId.get(selectedPair[0])!.camp as Camp.Good | Camp.Wolf, byId.get(selectedPair[1])!.camp as Camp.Good | Camp.Wolf],
    groupId: "cupid_lovers", mixed: byId.get(selectedPair[0])!.camp !== byId.get(selectedPair[1])!.camp,
  } : null;
  const memberIds = relation ? [...new Set([...relation.pairIds, ...(policy === DEFAULT_POLICY ? [actor.id] : [])])] : [];
  const initialMembers = new Map(initial.map((p) => [p.id, [{ kind: "faction", faction: p.camp }] as VictoryAffiliation[]]));
  const paidMember: VictoryAffiliation[] = relation
    ? [relation.mixed ? { kind: "relationship", groupId: relation.groupId } : { kind: "faction", faction: relation.pairCamps[0] }]
    : [];
  const selectionFacts = relation ? [
    { type: "cupid_lovers_chosen", payload: { actorId: actor.id, day: 1, pairIds: [...relation.pairIds] } },
    { type: "lover_recognized", payload: { actorId: relation.pairIds[0], partnerId: relation.pairIds[1] } },
    { type: "lover_recognized", payload: { actorId: relation.pairIds[1], partnerId: relation.pairIds[0] } },
    { type: "cupid_relation_resolved", payload: relation },
  ] : [];
  let published = 0;
  const deaths = new Set<string>(), derived = new Set<number>();
  for (const event of facts) {
    if (event.type !== "lovers_death") {
      const expected = selectionFacts[published++];
      if (!expected || event.type !== expected.type || !same(event.payload, expected.payload)) fail();
    } else {
      const root = event.payload.actorId, target = event.payload.targetId;
      if (!relation || published !== 4 || !relation.pairIds.includes(root as number) ||
        !relation.pairIds.includes(target as number) || root === target || deaths.has(`${root}:${target}`)) fail();
      deaths.add(`${root}:${target}`); derived.add(target as number);
    }
  }
  // 事实是 God 原流，玩家请求只能携带自己的选择或互认副本，不泄漏冻结阵营／关系结算或秘密牵连。
  for (const decision of record.decisions) {
    for (const event of decision.request.context.visible_events) {
      if (!(CUPID_EVENT_TYPES as readonly string[]).includes(event.type)) continue;
      const fact = readCupidEventFact(event.type, event.payload);
      if (!fact || !["cupid_lovers_chosen", "lover_recognized"].includes(event.type) ||
        fact.actorId !== decision.actorId || !facts.some((original) => original.type === event.type && same(original.payload, event.payload))) fail();
    }
    if ((decision.stage === "hunter_shot" || decision.stage === "death_shot") &&
      (decision.request.context.death_sources?.includes(DeathCause.Lovers) || derived.has(decision.actorId))) fail();
  }
  for (const event of record.events) {
    if ((event.type === "hunter_shot" && derived.has(event.payload.hunterId as number)) ||
      (["player_shot", "wolf_king_shot"].includes(event.type) && derived.has(event.payload.actorId as number))) fail();
  }

  // 每个数字是原写序中的可观察位置。不可见的 WeakMap／相同值组件写不被编造为独立档案证据。
  let minimumPrefix = 0, priorEventCount = 0;
  for (const [index, cp] of record.checkpoints.entries()) {
    if (cp.cycle !== index || cp.eventCount < priorEventCount || cp.eventCount > record.events.length ||
      cp.players.length !== initial.length || new Set(cp.players.map((p) => p.id)).size !== initial.length ||
      Boolean(cp.failure) !== !cp.complete) fail();
    priorEventCount = cp.eventCount;
    const current = cp.players.find((p) => p.id === actor.id), state = object(current?.privateState.cupid);
    if (!current || !state || !keys(state, ["policy", "remaining", "choice"]) || state.policy !== policy ||
      cp.players.some((p) => {
        const original = byId.get(p.id);
        return !original || p.role !== original.role || p.camp !== original.camp ||
          (p.id !== actor.id && (Object.hasOwn(p.privateState, "cupid") || p.lovers !== undefined));
      })) fail();
    const visibleFacts = record.events.slice(0, cp.eventCount)
      .filter((e) => (CUPID_EVENT_TYPES as readonly string[]).includes(e.type) && e.type !== "lovers_death").length;
    const choices = relation ? { day: 1, pairIds: [...relation.pairIds] } : null;
    const matches: number[] = [];
    const lastPrefix = relation ? 3 + memberIds.length + 4 : 0;
    for (let prefix = minimumPrefix; prefix <= lastPrefix; prefix++) {
      const bound = prefix >= 1;
      const installed = Math.max(0, Math.min(memberIds.length, prefix - 3));
      const factCount = Math.max(0, prefix - 3 - memberIds.length);
      if (same(current.lovers, bound ? relation : undefined) &&
        state.remaining === (prefix >= 2 ? 0 : 1) && same(state.choice, prefix >= 3 ? choices : null) &&
        visibleFacts === factCount && cp.players.every((p) => same(p.victory.affiliations,
          memberIds.slice(0, installed).includes(p.id) ? paidMember : initialMembers.get(p.id)))) matches.push(prefix);
    }
    if (!matches.length || (cp.cycle === 0 && (matches[0] !== 0 || cp.players.some((p) => !p.alive))) ||
      (cp.complete && cp.cycle > 0 && !matches.includes(lastPrefix)) ||
      (cp.complete && cp.cycle > 0 && !relation)) fail();
    minimumPrefix = cp.complete && cp.cycle > 0 ? lastPrefix : matches[0]!;
    // 只在完整周期核最终存活结果；失败周期中，lovers_death 已发表仍可能尚未完成标死。
    if ((cp.complete || cp.snapshot.result !== null) && cp.cycle > 0 && relation && record.events.slice(0, cp.eventCount).some((e) => e.type === "lovers_death") &&
      relation.pairIds.some((id) => cp.players.find((p) => p.id === id)!.alive)) fail();
    if (cp.snapshot.result) validateResult(cp, relation, memberIds, initialMembers, paidMember);
  }
  // 当前 liveEvents 可以领先最后 checkpoint；这里只核事实自身的成员，不伪造缺席的最终生命快照。
  for (const event of record.events) if (event.type === "game_over") {
    let result: ReturnType<typeof readVictoryResult>;
    try { result = readVictoryResult(event.payload, initial.map((p) => p.id)); } catch { return fail(); }
    if (result.outcome.kind === "victory") {
      const claim = result.outcome.primary;
      const expected = initial.filter((p) => (memberIds.includes(p.id) ? paidMember : initialMembers.get(p.id)!).some((a) =>
        (claim.kind === "faction" && a.kind === "faction" && a.faction === claim.faction) ||
        (claim.kind === "relationship" && a.kind === "relationship" && a.groupId === claim.groupId))).map((p) => p.id).sort((a, b) => a - b);
      if (claim.kind === "individual" || result.outcome.additional.length || !same(claim.winningPlayerIds, expected) ||
        !same(result.outcome.winningPlayerIds, expected)) fail();
    }
    const cp = record.checkpoints.find((p) => p.eventCount > record.events.indexOf(event) && p.snapshot.result);
    if (cp && !same(result, cp.snapshot.result)) fail();
  }
}

/** 独立按冻结 City 规则读完整 checkpoint；死者成员仍参与胜利名单，真实 Camp 与关系归属分开统计。 */
function validateResult(
  cp: RecordedCheckpoint,
  relation: LoversComponent | null,
  members: number[],
  initialMembers: Map<number, VictoryAffiliation[]>,
  paidMember: VictoryAffiliation[],
): void {
  const result = cp.snapshot.result!;
  if (result.outcome.kind === "no_winner") {
    if (result.winner !== null || result.reason !== "max_days_reached") fail();
    return;
  }
  // 封盘后的发表／收尾仍可能抛错；failure 不抹去已写入的真实终态。
  if (!relation) fail();
  const living = cp.players.filter((p) => p.alive);
  const wolves = living.filter((p) => p.camp === Camp.Wolf).length;
  const good = living.filter((p) => p.camp === Camp.Good && !(relation.policy === DEFAULT_POLICY &&
    p.id === relation.actorId && (relation.mixed || relation.pairCamps[0] === Camp.Wolf))).length;
  const groupWins = relation.mixed && relation.pairIds.every((id) => living.some((p) => p.id === id)) &&
    living.every((p) => members.includes(p.id));
  const target = groupWins ? { kind: "relationship", groupId: "cupid_lovers" } as const
    : wolves === 0 ? { kind: "faction", faction: Camp.Good } as const
    : good === 0 ? { kind: "faction", faction: Camp.Wolf } as const : null;
  const reason = groupWins ? "cupid_lovers_only_survivors" : wolves === 0 ? "all_wolves_eliminated" : "all_good_eliminated";
  if (!target) fail();
  const winners = cp.players.filter((p) => (members.includes(p.id) ? paidMember : initialMembers.get(p.id)!).some((a) =>
    target.kind === "faction" ? a.kind === "faction" && a.faction === target.faction
      : a.kind === "relationship" && a.groupId === target.groupId)).map((p) => p.id).sort((a, b) => a - b);
  if (result.reason !== reason || result.winner !== (target.kind === "faction" ? target.faction : null) ||
    !same(result.outcome, { kind: "victory", primary: { ...target, winningPlayerIds: winners }, additional: [], winningPlayerIds: winners })) fail();
}

/**
 * 负责严格 Tape 的原生 replay 装配、请求匹配与结算调度；输入为已记录归档和实际输出目录。
 * 输出为原生执行的事件／操作／checkpoint 与精确差异；真实 source、lock 和 RNG 身份必须先匹配。
 * 记录请求规范化由轨迹模块提供；本执行器保留自己的消费、等待、游标与清理，不创建兼容来源或改写原归档。
 */
import { unwrapRecordingEnvelope } from "@ai-werewolf-arena/replay-contract";
import { reproductionIdentitiesMatch } from "../../recording/archive_identity";
import { initialPlayerIdentity } from "../../core/domain/initial_roster";
import { initialIdentityDeal } from "../../game/mechanisms/roles/initial_identity/deal";
import type { Locale } from "@ai-werewolf-arena/game-contract";
import { readFile } from "node:fs/promises";
import { RULESET } from "@ai-werewolf-arena/game-catalog";
import { bootstrapGame } from "../../app/bootstrap";
import {
  createRandom,
  RANDOM_ALGORITHM,
  RANDOM_STREAM_POLICY,
  type ActionProvider,
  type ActionRequest,
  type GameEvent,
} from "../../core";
import { parseReproductionRecord, recordedErrorName, type RecordedDecision, type RecordedGameEvent, type ReproductionRecord } from "../../recording/reproduction";
import { normalizedRequest } from "../../recording/reproduction-trace";
import { SessionRecordManager } from "../../recording/session_recorder";
import { runWithSessionRecorder } from "../../recording/recording_context";
import { GameEventRecorder } from "../game_event_recorder";
import { captureCheckpoint, currentEngineVersion } from "./reproduction_context";

function stableJson(value: unknown): string {
  const sort = (item: unknown): unknown => {
    if (Array.isArray(item)) return item.map(sort);
    if (item && typeof item === "object")
      return Object.fromEntries(
        Object.entries(item)
          .filter(([, value]) => value !== undefined)
          .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
          .map(([key, value]) => [key, sort(value)]),
      );
    return item;
  };
  return JSON.stringify(sort(value));
}

export class ReproductionMismatchError extends Error {}
function requireMatch(condition: boolean, code: string): asserts condition {
  if (!condition) throw new ReproductionMismatchError(code);
}

function decisionKey(decision: Pick<RecordedDecision, "actorId" | "day" | "stage" | "turn">) {
  return `${decision.actorId}/${decision.day}/${decision.stage}/${decision.turn}`;
}

class RecordedActions implements ActionProvider {
  private readonly decisions = new Map<string, RecordedDecision>();
  private readonly turns = new Map<string, number>();
  private readonly consumed = new Set<string>();
  private readonly openings = new Map<number, Set<string>>();
  private nextSettlement = 1;
  private eventCursor?: () => number;
  setEventCursor(cursor: () => number): void {
    if (this.eventCursor) throw Error("reproduction_provider_cursor_already_bound");
    this.eventCursor = cursor;
  }
  get cursors() {
    return { settlementCount: this.nextSettlement - 1, decisionCount: this.consumed.size };
  }
  private settlementScheduled = false;
  private deadlockTimer?: ReturnType<typeof setTimeout>;
  private readonly total: number;
  private readonly settlementWaiters: Array<{
    resolve: () => void;
    reject: (error: unknown) => void;
  }> = [];
  private readonly pending = new Map<
    number,
    {
      decision: RecordedDecision;
      resolve: (action: import("../../core").ToolCall | null) => void;
      reject: (error: unknown) => void;
    }
  >();
  constructor(record: ReproductionRecord) {
    this.total = record.decisions.length;
    const orders = record.decisions
      .map((decision) => decision.settleOrder)
      .sort((a, b) => (a ?? 0) - (b ?? 0));
    requireMatch(
      orders.every((order, index) => order === index + 1) &&
        record.decisions.every(
          (decision) => decision.openedAfterSettlement < decision.settleOrder!,
        ),
      "reproduction_settlement_order_invalid",
    );
    for (const decision of record.decisions) {
      const key = decisionKey(decision);
      requireMatch(
        !this.decisions.has(key) &&
          decision.request.actorId === decision.actorId &&
          decision.request.context.day === decision.day &&
          decision.request.context.stage === decision.stage,
        "reproduction_decision_invalid",
      );
      this.decisions.set(key, decision);
      if (!this.openings.has(decision.openedAfterSettlement))
        this.openings.set(decision.openedAfterSettlement, new Set());
      this.openings.get(decision.openedAfterSettlement)!.add(key);
    }
  }

  getAction(request: ActionRequest): Promise<import("../../core").ToolCall | null> {
    const base = `${request.actorId}/${request.context.day}/${request.context.stage}`;
    const turn = (this.turns.get(base) ?? 0) + 1;
    this.turns.set(base, turn);
    const key = `${base}/${turn}`;
    const decision = this.decisions.get(key);
    requireMatch(Boolean(decision), "reproduction_unexpected_request");
    requireMatch(
      stableJson(normalizedRequest(request)) === stableJson(decision!.request),
      "reproduction_observation_mismatch",
    );
    requireMatch(
      decision!.openedAfterSettlement === this.nextSettlement - 1,
      "reproduction_opening_boundary_mismatch",
    );
    if (decision!.openedAtEventCount !== undefined)
      requireMatch(
        this.eventCursor?.() === decision!.openedAtEventCount,
        "reproduction_request_event_boundary_mismatch",
      );
    this.consumed.add(key);
    return new Promise((resolve, reject) => {
      this.pending.set(decision!.settleOrder!, { decision: decision!, resolve, reject });
      this.scheduleSettlement();
    });
  }

  private scheduleSettlement() {
    if (this.settlementScheduled) return;
    this.settlementScheduled = true;
    queueMicrotask(() => {
      this.settlementScheduled = false;
      while (this.pending.has(this.nextSettlement) && this.boundaryOpened()) {
        const { decision, resolve, reject } = this.pending.get(this.nextSettlement)!;
        this.pending.delete(this.nextSettlement++);
        if (decision.outcome.kind === "error") {
          const error = new Error("reproduction_recorded_decision_failed");
          error.name = decision.outcome.name;
          reject(error);
        } else if (decision.outcome.kind === "action")
          resolve(structuredClone(decision.outcome.action));
        else reject(new ReproductionMismatchError("reproduction_decision_pending"));
        if (this.nextSettlement > this.total)
          for (const waiter of this.settlementWaiters.splice(0)) waiter.resolve();
      }
      if ((this.pending.size || this.settlementWaiters.length) && !this.deadlockTimer) {
        // 离线引擎只推进本地决定工作；微任务耗尽后仍没有因果上的下一请求，
        // 表示被改动的录制无法继续，按原定时边界检查死锁。
        this.deadlockTimer = setTimeout(() => {
          this.deadlockTimer = undefined;
          if (
            this.nextSettlement <= this.total &&
            (!this.pending.has(this.nextSettlement) || !this.boundaryOpened())
          )
            this.close(new ReproductionMismatchError("reproduction_causal_order_invalid"));
        }, 0);
      }
    });
  }

  private boundaryOpened() {
    return [...(this.openings.get(this.nextSettlement - 1) ?? [])].every((key) =>
      this.consumed.has(key),
    );
  }

  close(error = new ReproductionMismatchError("reproduction_replay_closed")) {
    if (this.deadlockTimer) clearTimeout(this.deadlockTimer);
    this.deadlockTimer = undefined;
    for (const pending of this.pending.values()) pending.reject(error);
    this.pending.clear();
    for (const waiter of this.settlementWaiters.splice(0)) waiter.reject(error);
  }

  waitForSettlements(): Promise<void> {
    if (this.nextSettlement > this.total) return Promise.resolve();
    return new Promise((resolve, reject) => {
      this.settlementWaiters.push({ resolve, reject });
      this.scheduleSettlement();
    });
  }

  assertConsumed() {
    requireMatch(this.consumed.size === this.decisions.size, "reproduction_unconsumed_decisions");
  }
}

function normalizedEvents(events: readonly (GameEvent | RecordedGameEvent)[]) {
  return events.map(({ timestamp: _timestamp, ...event }) => event);
}

/** 文件入口同时保留真实声明和原 payload；CLI 不在读文件后丢弃 header 再执行。 */
export async function readReproductionArchive(file: string) {
  const raw = await readFile(file, "utf8");
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    throw new Error("reproduction_json_invalid");
  }
  const archive = unwrapRecordingEnvelope(value, "strict_reproduction");
  return { record: parseReproductionRecord(archive.payload), identities: archive.identities, input: value };
}

/** 旧数据消费 API 只返回 canonical Tape；执行文件需使用 readReproductionArchive 保留声明。 */
export async function readReproduction(file: string): Promise<ReproductionRecord> {
  return (await readReproductionArchive(file)).record;
}

/** 按真实引擎复现记录行动；不加载模型传输或认证，显式身份不能放宽精确构建检查。 */
export async function replayReproduction(
  input: unknown,
  recordRoot: string,
  displayLocale?: Locale,
) {
  const archive = unwrapRecordingEnvelope(input, "strict_reproduction");
  const record = parseReproductionRecord(archive.payload);
  requireMatch(
    record.finalized &&
      record.termination !== null &&
      record.decisions.every((item) => item.outcome.kind !== "pending"),
    "reproduction_not_finalized",
  );
  const version = await currentEngineVersion();
  requireMatch(
    record.metadata.engine.sourceHash === version.sourceHash &&
      record.metadata.engine.lockHash === version.lockHash,
    "reproduction_engine_or_lock_incompatible",
  );
  requireMatch(
    record.metadata.random.algorithm === RANDOM_ALGORITHM &&
      record.metadata.random.streamPolicy === RANDOM_STREAM_POLICY &&
      record.metadata.random.path.every((name) => name.trim().length > 0),
    "reproduction_rng_incompatible",
  );
  requireMatch(
    record.metadata.ruleset.id === RULESET.id &&
      record.metadata.ruleset.version === RULESET.version,
    "reproduction_ruleset_incompatible",
  );
  // 语义声明在原精确来源／RNG／规则检查之后验证；不能用手写版本打开旧构建。
  requireMatch(reproductionIdentitiesMatch(archive.identities, record), "reproduction_contract_identity_incompatible");
  // 内层 Tape 已通过原严格板子 schema；不要再次用更窄的公开配置重建，
  // 否则会丢失历史可选字段并更改默认值。
  const board = record.metadata.normalizedBoard;
  requireMatch(
    record.metadata.players.length === board.boardSize &&
      record.metadata.players.every((player, index) => player.id === index + 1),
    "reproduction_players_invalid",
  );
  requireMatch(
    record.checkpoints.every(
      (checkpoint, index) =>
        checkpoint.cycle === index &&
        (checkpoint.complete || index === record.checkpoints.length - 1) &&
        Boolean(checkpoint.failure) === !checkpoint.complete &&
        checkpoint.eventCount <= record.events.length,
    ),
    "reproduction_checkpoints_invalid",
  );
  requireMatch(
    record.checkpoints[0].complete &&
      record.checkpoints.at(-1)!.eventCount === record.events.length,
    "reproduction_event_count_invalid",
  );
  const finalResult = record.checkpoints.at(-1)!.snapshot.result;
  const finalCheckpoint = record.checkpoints.at(-1)!;
  requireMatch(
    finalCheckpoint.snapshot.gameOver === (finalResult !== null),
    "reproduction_termination_invalid",
  );
  const recordedErrors = record.termination!.errors;
  const cycleErrors = recordedErrors.filter((error) => error.scope === "cycle");
  const reason = record.termination!.reason;
  requireMatch(
    record.termination!.winner === (finalResult?.winner ?? null) &&
      (reason === "runtime_error"
        ? recordedErrors.length > 0
        : finalResult
          ? reason === finalResult.reason
          : reason === "runtime_timeout" && finalCheckpoint.complete) &&
      (finalCheckpoint.complete
        ? cycleErrors.length === 0
        : reason === "runtime_error" &&
          cycleErrors.length === 1 &&
          cycleErrors[0].name === finalCheckpoint.failure!.name),
    "reproduction_termination_invalid",
  );
  const provider = new RecordedActions(record);
  let random = createRandom(record.metadata.random.seed);
  for (const name of record.metadata.random.path) random = random.fork(name);
  const context = bootstrapGame(board, {
    random,
    locale: record.metadata.locale,
    ...(record.metadata.faultPlan ? { faultPlan: record.metadata.faultPlan } : {}),
    ...(record.metadata.dealMode === "fixed"
      ? {
          fixedRoles:
            record.metadata.initialDeal ?? record.metadata.players.map((player) => player.role),
        }
      : {}),
    playerNames: Object.fromEntries(
      record.metadata.players.map((player) => [String(player.id), player.name]),
    ),
  });
  requireMatch(
    stableJson(initialIdentityDeal(context.world) ?? null) ===
      stableJson(record.metadata.initialDeal ?? null),
    "reproduction_initial_deal_mismatch",
  );
  if (board.animalDream || board.nobleSecretBody || board.fragrantPairSeer)
    provider.setEventCursor(() => context.phaseManager.getEvents().length);
  const initial = captureCheckpoint(
    context.world,
    context.phaseManager.getSnapshot(),
    0,
    true,
    context.phaseManager.getEvents().length,
  );
  requireMatch(
    stableJson(initial) === stableJson(record.checkpoints[0]),
    "reproduction_initial_state_mismatch",
  );
  requireMatch(
    stableJson(
      initial.players.map((player) => ({
        id: player.id,
        role: player.role,
        camp: player.camp,
        name: player.name,
      })),
    ) === stableJson(record.metadata.players.map(({ agent: _agent, ...player }) => player)),
    "reproduction_identity_mismatch",
  );
  const manager = await SessionRecordManager.create(
    {
      sessionId: `reproduction-${crypto.randomUUID()}`,
      board: record.metadata.boardId,
      locale: context.world.locale,
      startedAtIso: new Date().toISOString(),
      random: context.random.metadata,
    },
    recordRoot,
    displayLocale ?? record.metadata.locale,
  );
  if (board.animalDream || board.nobleSecretBody || board.fragrantPairSeer)
    manager.setReplayEventCursor(() => context.phaseManager.getEvents().length);
  const recorder = new GameEventRecorder(
    { world: context.world, replayManager: manager },
    context.phaseManager.getSnapshot().phase,
  );
  let summary: Awaited<ReturnType<SessionRecordManager["finalize"]>> | undefined;
  await runWithSessionRecorder(manager, async () => {
    const failures: unknown[] = [];
    try {
      for (const checkpoint of record.checkpoints.slice(1)) {
        let complete = false;
        let cycleFailure: unknown;
        try {
          await context.phaseManager.runSingleCycle(provider, record.metadata.maxDays);
          // 周期成功也须核对原角色名册与合法库存，再标记 complete；不跳过成功路径的 checkpoint 校验。
          captureCheckpoint(
            context.world,
            context.phaseManager.getSnapshot(),
            checkpoint.cycle,
            true,
            context.phaseManager.getEvents().length,
          );
          complete = true;
        } catch (error) {
          if (error instanceof ReproductionMismatchError || checkpoint.complete) throw error;
          cycleFailure = error;
          requireMatch(
            checkpoint.failure!.name === recordedErrorName(error),
            "reproduction_failure_mismatch",
          );
        }
        const actual = captureCheckpoint(
          context.world,
          context.phaseManager.getSnapshot(),
          checkpoint.cycle,
          complete,
          context.phaseManager.getEvents().length,
          cycleFailure,
          provider.cursors,
        );
        requireMatch(
          stableJson(actual) === stableJson(checkpoint),
          "reproduction_checkpoint_mismatch",
        );
        recorder.flush(context.phaseManager.getEvents());
      }
      await provider.waitForSettlements();
      provider.assertConsumed();
      if (record.checkpoints.at(-1)!.complete) context.phaseManager.assertFaultPlanConsumed();
      requireMatch(
        stableJson(normalizedEvents(context.phaseManager.getEvents())) ===
          stableJson(normalizedEvents(record.events)),
        "reproduction_events_mismatch",
      );
    } catch (error) {
      failures.push(error);
    } finally {
      provider.close();
      try {
        recorder.flush(context.phaseManager.getEvents());
      } catch (error) {
        failures.push(error);
      }
      try {
        summary = await manager.finalize({
          endedAtIso: new Date().toISOString(),
          winner: context.phaseManager.getSnapshot().result?.winner ?? null,
          ...(context.phaseManager.getSnapshot().result
            ? { gameResult: context.phaseManager.getSnapshot().result! }
            : {}),
          finishReason: failures.length ? "runtime_error" : record.termination!.reason,
          players: captureCheckpoint(
            context.world,
            context.phaseManager.getSnapshot(),
            0,
            record.checkpoints.at(-1)!.complete,
            0,
          ).players.map((player, index) => ({
            player_id: player.id,
            name: player.name,
            role:
              initialPlayerIdentity(context.world, player.id)?.role ??
              initialIdentityDeal(context.world)?.[index] ??
              player.role,
            camp:
              initialPlayerIdentity(context.world, player.id)?.camp ??
              (initialIdentityDeal(context.world)
                ? record.metadata.players[index]!.camp
                : player.camp),
            alive: player.alive,
          })),
        });
      } catch (error) {
        failures.push(error);
      }
    }
    if (failures.length === 1) throw failures[0];
    if (failures.length) throw new AggregateError(failures, "reproduction_replay_failed");
  });
  // 并行预检完成可能重排操作；仍比较完整领域操作多重集，不丢失重复项或字段。
  const actualOps = (summary!.logicOps ?? [])
    .filter((op) => op.scope !== "llm_action_provider")
    .map(({ seq: _seq, timestamp: _timestamp, ...op }) => stableJson(op))
    .sort();
  const recordedOps = record.operations.map((op) => stableJson(op)).sort();
  requireMatch(
    stableJson(actualOps) === stableJson(recordedOps),
    "reproduction_operations_mismatch",
  );
  return {
    seed: record.metadata.random.seed,
    snapshot: context.phaseManager.getSnapshot(),
    sourceTermination: record.termination,
    eventCount: context.phaseManager.getEvents().length,
    decisionCount: record.decisions.length,
    recordDir: manager.sessionDir,
  };
}

/**
 * 向后端和浏览器公开原 schema 2 复盘、历史转换与显式封装 reader；输入为纯数据归档。
 * 输出保留原规范化 document，旧未声明／v1／v2 reader 规则与原文不变；新封装身份不表示可执行授权。
 * 游戏结算与严格来源兼容仍由后端实际执行器负责，本出口不导入 Node、World 或 renderer。
 */
import { isRecord, assertField, assertSerializedData, ReplayDocumentValidationError } from "./validation";
export { ReplayDocumentValidationError } from "./validation";
import { isLocale, type Locale, type SealedVictoryResult } from "@ai-werewolf-arena/game-contract";
import { unwrapRecordingEnvelope, type RecordingIdentities } from "./archive-envelope";
import { readVictoryResult } from "./outcomes";
import {
  legacyPhaseId,
  legacyStageId,
  legacyRoleId,
  legacyCampId,
  legacyResultReasonId,
} from "./legacy_aliases";
export * from "./legacy_aliases";
export const REPLAY_SCHEMA_VERSION = 2 as const;
export * from "./inspection";
export * from "./gravekeeper";
export * from "./outcomes";

/**
 * 浏览器与视频消费的公开复盘数据形状；展示视图不充当已持久化完整归档。
 *
 * `god` 为完整裁判视角，包含每个角色和所有公开事件，
 * 也支持仍进行中的对局；执行来源与版本声明由新 envelope 独立记录。
 */
export type ReplayPerspective = "god";

export interface ReplayEvent {
  seq: number;
  timestamp: string;
  phase: string;
  day: number;
  stage?: string;
  type: string;
  payload: Record<string, unknown>;
}

export interface ReplayDocument {
  schemaVersion: typeof REPLAY_SCHEMA_VERSION;
  sessionId: string;
  perspective: ReplayPerspective;
  meta: {
    locale?: Locale;
    board: string;
    startedAt: string;
    endedAt: string;
  };
  result: {
    winner: string | null;
    reason: string | null;
    /** 明确的引擎判胜，与执行结束原因分别记录。 */
    decision?: SealedVictoryResult;
  };
  players: Array<{
    player_id: number;
    role: string;
    camp: string;
    name?: string;
  }>;
  events: ReplayEvent[];
}

/** 校验未筛选的原规范 document，事件序号从一开始；不推导游戏规则。 */
function assertReplayShape(
  value: unknown,
): asserts value is Omit<ReplayDocument, "schemaVersion"> & { schemaVersion?: unknown } {
  if (
    !isRecord(value) ||
    value.perspective !== "god" ||
    typeof value.sessionId !== "string" ||
    !Array.isArray(value.events)
  ) {
    throw new ReplayDocumentValidationError("invalid_document", "document");
  }
  if (!isRecord(value.meta) || !isRecord(value.result) || !Array.isArray(value.players)) {
    throw new ReplayDocumentValidationError("missing_fields", "meta/result/players");
  }

  assertField(value.meta.locale === undefined || isLocale(value.meta.locale), "meta.locale");
  assertField(typeof value.meta.board === "string", "meta.board");
  assertField(typeof value.meta.startedAt === "string", "meta.startedAt");
  assertField(typeof value.meta.endedAt === "string", "meta.endedAt");
  assertField(
    value.result.winner === null || typeof value.result.winner === "string",
    "result.winner",
  );
  assertField(
    value.result.reason === null || typeof value.result.reason === "string",
    "result.reason",
  );

  const playerIds = new Set<number>();
  for (let index = 0; index < value.players.length; index += 1) {
    const player: unknown = value.players[index];
    const path = `players[${index}]`;
    assertField(isRecord(player), path);
    assertField(
      typeof player.player_id === "number" &&
        Number.isSafeInteger(player.player_id) &&
        player.player_id > 0,
      `${path}.player_id`,
    );
    assertField(!playerIds.has(player.player_id), `${path}.player_id`);
    playerIds.add(player.player_id);
    assertField(typeof player.role === "string", `${path}.role`);
    assertField(typeof player.camp === "string", `${path}.camp`);
    assertField(player.name === undefined || typeof player.name === "string", `${path}.name`);
  }

  for (let index = 0; index < value.events.length; index += 1) {
    const event: unknown = value.events[index];
    const path = `events[${index}]`;
    assertField(isRecord(event), path);
    assertField(event.seq === index + 1, `${path}.seq`);
    assertField(typeof event.timestamp === "string", `${path}.timestamp`);
    assertField(typeof event.phase === "string", `${path}.phase`);
    assertField(
      typeof event.day === "number" && Number.isSafeInteger(event.day) && event.day >= 0,
      `${path}.day`,
    );
    assertField(event.stage === undefined || typeof event.stage === "string", `${path}.stage`);
    assertField(typeof event.type === "string", `${path}.type`);
    assertField(isRecord(event.payload), `${path}.payload`);
  }
  const decision = Object.getOwnPropertyDescriptor(value.result, "decision");
  if (decision) {
    assertField("value" in decision && decision.enumerable === true, "result.decision");
    const parsed = readVictoryResult(decision.value, [...playerIds]);
    assertField(parsed.winner === value.result.winner, "result.winner");
  }
  const explicit: SealedVictoryResult[] = [];
  if (decision && "value" in decision)
    explicit.push(readVictoryResult(decision.value, [...playerIds]));
  for (const event of value.events) {
    if (
      event.type !== "game_over" ||
      !isRecord(event.payload) ||
      (!Object.hasOwn(event.payload, "outcome") && !Object.hasOwn(event.payload, "decidedAt"))
    )
      continue;
    assertSerializedData(event.payload, "events.game_over.payload");
    try {
      explicit.push(readVictoryResult(event.payload, [...playerIds]));
    } catch {
      /* 独立非法终局事实继续保留为未知原事件，不生成替代判胜。 */
    }
  }
  if (explicit.length > 1)
    assertField(
      explicit.every((item) => JSON.stringify(item) === JSON.stringify(explicit[0])),
      "result.decision_terminal_mismatch",
    );
}

/** 原 canonical v2 writer 契约；历史文件及显式新封装由 reader 单独判版本。 */
export function assertReplayDocument(value: unknown): asserts value is ReplayDocument {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  assertReplayShape(value);
  if (value.schemaVersion !== REPLAY_SCHEMA_VERSION)
    throw new ReplayDocumentValidationError("unsupported_version", "schemaVersion");
}

/** 只读转换，先判封装和内层版本再解释历史别名；昵称、发言等用户原文不改写。 */
export function readReplayDocument(value: unknown): ReplayDocument {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  value = unwrapRecordingEnvelope(value, "public_replay").payload;
  if (!isRecord(value)) throw new ReplayDocumentValidationError("invalid_document", "document");
  const version = value.schemaVersion;
  if (version !== undefined && version !== 1 && version !== REPLAY_SCHEMA_VERSION)
    throw new ReplayDocumentValidationError("unsupported_version", "schemaVersion");
  assertReplayShape(value);
  if (version === REPLAY_SCHEMA_VERSION) {
    const result = structuredClone(value);
    assertReplayDocument(result);
    return result as ReplayDocument;
  }
  const result = structuredClone(value) as ReplayDocument;
  result.schemaVersion = REPLAY_SCHEMA_VERSION;
  result.players = result.players.map((player) => ({
    ...player,
    role: legacyRoleId(player.role),
    camp: legacyCampId(player.camp),
  }));
  result.result.winner = result.result.winner === null ? null : legacyCampId(result.result.winner);
  result.result.reason =
    result.result.reason === null ? null : legacyResultReasonId(result.result.reason);
  result.events = result.events.map((event) => {
    const payload = { ...event.payload };
    if (event.type === "phase_changed" && typeof payload.phase === "string")
      payload.phase = legacyPhaseId(payload.phase);
    if (event.type === "game_over" || event.type === "phase_changed") {
      if (typeof payload.winner === "string") payload.winner = legacyCampId(payload.winner);
      if (typeof payload.reason === "string") payload.reason = legacyResultReasonId(payload.reason);
    }
    if (event.type === "god_private_game_info" && Array.isArray(payload.players))
      payload.players = payload.players.map((player) =>
        isRecord(player)
          ? {
              ...player,
              ...(typeof player.role === "string" ? { role: legacyRoleId(player.role) } : {}),
              ...(typeof player.camp === "string" ? { camp: legacyCampId(player.camp) } : {}),
            }
          : player,
      );
    return {
      ...event,
      phase: legacyPhaseId(event.phase),
      ...(event.stage === undefined ? {} : { stage: legacyStageId(event.stage) }),
      payload,
    };
  });
  assertReplayDocument(result);
  return result;
}

export * from "./player_record";

export * from "./error_diagnostic";

export * from "./archive-envelope";

/** 前端 canonical 入口保留声明供真实展示支持检查；旧裸档返回 null，不猜造历史身份。 */
export function readReplayArchive(value: unknown): { replay: ReplayDocument; identities: RecordingIdentities | null } {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  const archive = unwrapRecordingEnvelope(value, "public_replay");
  return { replay: readReplayDocument(archive.payload), identities: archive.identities };
}

export * from "./manifest";

/**
 * 负责运行时死亡枪选择与死因资格政策。输入为原生命句柄、死因、政策和来源阶段；
 * 输出为选择类型及原 permitsDeathShot／permitsHunterShot 结果，保持原拒绝顺序。
 * 序列化死因来自公共契约，回调、组件引用与行动权限仅留在领域内部。
 * 混合死因必须全部合格，不能用其中一项狼刀／放逐掩盖毒或关系牵连的抑制。
 */
import { Phase } from "./identity";
import type { DeathActionPolicy } from "./board";
import type { NightLifeScope } from "./night_effects";
import { DeathCause } from "@ai-werewolf-arena/game-contract";
export { DeathCause } from "@ai-werewolf-arena/game-contract";
export type { DeathSources } from "@ai-werewolf-arena/game-contract";

/** shot／pass 带原行动窗口 ID；invalid 未授权，不能被当作已付款的弃枪。 */
export type DeathShotSelection =
  | {
      kind: "shot";
      targetId: number;
      deathActionId: number;
      targetScope?: NightLifeScope;
      mappedMiss?: true;
      mappingCurrent?: () => boolean;
    }
  | { kind: "pass"; deathActionId: number }
  | { kind: "invalid" };

export function permitsDeathShot(
  sources: readonly DeathCause[],
  policy: DeathActionPolicy = "awa_qualified_sources_v1",
  deathPhase?: Phase,
): boolean {
  // day 政策先限制死亡来源为白天／放逐；knife-or-exile 不接受枪击和白狼爆炸。
  if (policy === "awa_day_deaths_v1" && deathPhase !== Phase.Day && deathPhase !== Phase.Voting)
    return false;
  if (
    policy !== "awa_qualified_sources_v1" &&
    policy !== "awa_knife_or_exile_v1" &&
    policy !== "awa_day_deaths_v1"
  )
    return false;
  // 先拒绝未知政策，再逐项校验；混合来源不以“存在一项合格”放宽枪权。
  return (
    sources.length > 0 &&
    sources.every(
      (source) =>
        source === DeathCause.WolfKill ||
        source === DeathCause.MechanicalKnife ||
        source === DeathCause.AwakenedHiddenKnife ||
        source === DeathCause.Exile ||
        (policy !== "awa_knife_or_exile_v1" &&
          (source === DeathCause.Shot || source === DeathCause.WhiteWolfBlast)),
    )
  );
}
/** 猎人兼容入口直接复用同一资格政策，不能维护第二套死因规则。 */
export const permitsHunterShot = permitsDeathShot;

/**
 * 负责按遗言政策判定资格，并为已死亡玩家发表遗言授予事实。
 * 输入为死亡阶段、日期、原死因及可选初始波上下文；记录入口另接收 World 与待写事件数组。
 * 输出为资格布尔值和 last_words_granted 事件；实际生命仍在写入前检查，规则未知则拒绝。
 * 此机制不执行玩家发言、更新死亡波或判胜，发言与阶段推进归原调用流程。
 */
/** 文件说明：遗言规则与事件写入机制。 */
import type { LastWordsPolicy } from "../../../core/domain/board";
import { AliveComponent } from "../../../core/domain/components/alive";
import { COMPONENT } from "../../../core/domain/components/names";
import {
  EntityId,
  GameEvent,
  Phase,
  DeathCause,
  type DeathSources,
} from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { FRAGRANT_PAIR_POLICY } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
export interface LastWordsGrantContext {
  policy: typeof FRAGRANT_PAIR_POLICY;
  initialWave: boolean;
}

/** 遗言机制：判定是否可遗言并写入遗言授权事件。 */
export class LastWordsMechanism {
  /** 这里只判来源阶段、日期与死因；基础政策是否初始波由调用方筛选，不凭资格布尔值直接开放发言。 */
  shouldGrantLastWords(
    deathPhase: Phase,
    day: number,
    sources: readonly DeathCause[],
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): boolean {
    // 具名政策要求全部原因已知，再允许白天／投票及首夜夜死；不借当前执行阶段猜测死亡来源。
    if (policy === "netease_2017_day_and_first_night_v1") {
      if (!sources.length || sources.some((source) => !Object.values(DeathCause).includes(source)))
        return false;
      return (
        deathPhase === Phase.Day ||
        deathPhase === Phase.Voting ||
        (deathPhase === Phase.Night && day === 1)
      );
    }
    if (policy !== "awa_initial_wave_v1") return false;
    if (
      sources.length === 0 ||
      sources.includes(DeathCause.SelfDestruct) ||
      sources.includes(DeathCause.WhiteWolfBlast)
    )
      return false;
    if (deathPhase === Phase.Day && sources.every((source) => source === DeathCause.DuelFailure))
      return true;
    return (
      (deathPhase === Phase.Night &&
        day === 1 &&
        sources.some(
          (source) =>
            source === DeathCause.WolfKill ||
            (source === DeathCause.FragrantLink &&
              context?.policy === FRAGRANT_PAIR_POLICY &&
              context.initialWave) ||
            source === DeathCause.AwakenedHiddenKnife ||
            source === DeathCause.Poison ||
            source === DeathCause.Dream ||
            source === DeathCause.FoxInspection ||
            source === DeathCause.MerchantBacklash ||
            source === DeathCause.BlackMarketBacklash,
        )) ||
      (deathPhase === Phase.Voting && sources.includes(DeathCause.Exile))
    );
  }

  /** 逐人再次核死因政策与实际死亡，只写授予事实；等待玩家、打开生命许可和记录发言归结算器。 */
  recordLastWordsGranted(
    world: World,
    deadIds: EntityId[],
    deathPhase: Phase,
    lastWordsPhase: Phase,
    day: number,
    events: GameEvent[],
    sources: DeathSources,
    deathPhases: Readonly<Record<EntityId, Phase>> = {},
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): void {
    for (const deadId of deadIds) {
      if (
        !this.shouldGrantLastWords(
          deathPhases[deadId] ?? deathPhase,
          day,
          sources[deadId] ?? [],
          policy,
          context,
        )
      ) {
        continue;
      }
      const alive = world.getComponent(deadId, COMPONENT.Alive);
      if (!alive || alive.alive) {
        continue;
      }
      events.push({
        timestamp: Date.now(),
        type: "last_words_granted",
        payload: {
          playerId: deadId,
          phase: lastWordsPhase,
          day,
        },
      });
    }
  }
}

let defaultMechanism: LastWordsMechanism | null = null;

/** 获取默认遗言机制实例。 */
export function getDefaultLastWordsMechanism(): LastWordsMechanism {
  if (!defaultMechanism) {
    defaultMechanism = new LastWordsMechanism();
  }
  return defaultMechanism;
}
